// Convert the uploaded PDF to base64 and build the OpenAI request body
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (!keys.length) {
  throw new Error('No PDF was uploaded. Please upload an invoice in PDF format.');
}

const binaryKey = keys[0];
const file = item.binary[binaryKey];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString('base64');
const fileName = file.fileName || 'invoice.pdf';

const prompt = [
  'You are an accounting assistant that reads invoices.',
  'Extract the following fields from the attached invoice PDF:',
  '- vendor: the name of the company that issued the invoice',
  '- invoice_number: the invoice number or ID (empty string if not found)',
  '- invoice_date: the invoice issue date in YYYY-MM-DD format (empty string if not found)',
  '- currency: the 3-letter currency code, for example USD, PKR, EUR (empty string if not found)',
  '- total_amount: the final total amount due as a plain number, with no currency symbol or thousands separators (null if not found)',
  'Never guess or invent values.'
].join('\n');

return [{
  json: {
    fileName,
    requestBody: {
      model: 'gpt-4o-mini',
      temperature: 0,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          {
            type: 'file',
            file: {
              filename: fileName,
              file_data: 'data:application/pdf;base64,' + base64
            }
          }
        ]
      }],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'invoice_extraction',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              vendor: { type: 'string' },
              invoice_number: { type: 'string' },
              invoice_date: { type: 'string' },
              currency: { type: 'string' },
              total_amount: { type: ['number', 'null'] }
            },
            required: ['vendor', 'invoice_number', 'invoice_date', 'currency', 'total_amount'],
            additionalProperties: false
          }
        }
      }
    }
  }
}];

// Read OpenAI's JSON answer and shape one clean row for Google Sheets
const res = $input.first().json;
const message = res?.choices?.[0]?.message;

if (message?.refusal) {
  throw new Error('OpenAI refused the request: ' + message.refusal);
}

const text = message?.content;
if (!text) {
  throw new Error('OpenAI returned no content: ' + JSON.stringify(res).slice(0, 300));
}

let data;
try {
  data = JSON.parse(text);
} catch (e) {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Could not parse OpenAI output as JSON: ' + text.slice(0, 200));
  data = JSON.parse(match[0]);
}

const fileName = $('Prepare PDF for OpenAI').first().json.fileName;

return [{
  json: {
    processed_at: new Date().toISOString(),
    file_name: fileName,
    vendor: (data.vendor ?? '').toString().trim(),
    invoice_number: (data.invoice_number ?? '').toString().trim(),
    invoice_date: (data.invoice_date ?? '').toString().trim(),
    currency: (data.currency ?? '').toString().trim(),
    total_amount: (data.total_amount === null || data.total_amount === undefined) ? '' : data.total_amount
  }
}];
